  const id = 'i' + (++SEQ); D.invoices.push({ id, number: g('n'), cust: c.id, issue: g('i'), due: g('d'), total: parseFloat(g('a')), cur: c.cur, life: 'issued', po: g('po'), desc: '' }); audit('invoice.created', g('n'), money(parseFloat(g('a')), c.cur)); closeOv(); toast('Invoice created'); go('#/invoices/' + id);
