  const n = D.adjustments.length + 1, adj = { id: 'adj' + n, number: 'ADJ-' + String(n).padStart(4, '0'), inv: i.id, type: g('t'), amount: a, reason: g('r'), status: own ? 'applied' : 'pending_approval', approval: null };
  if (!own) { const ap = { id: 'ap' + (D.approvals.length + 1), number: 'APR-' + String(D.approvals.length + 1).padStart(4, '0'), type: g('t'), subject: i.id, amount: a, by: 'u2', status: 'pending', created: TODAY, reason: g('r'), ev: ['Invoice ' + i.number] }; D.approvals.push(ap); adj.approval = ap.id; audit('approval.requested', ap.number, `${ATYPE[g('t')]} ${money(a, i.cur)} on ${i.number}`); }
