ACT.saveDispute = () => { const f = $('#fd'); if (!validate(f)) return; const g = n => $(`[name=${n}]`, f).value, i = inv(g('i')), n = D.disputes.length + 1, id = 'd' + (++SEQ); D.disputes.push({ id, number: 'DSP-' + String(n).padStart(4, '0'), inv: i.id, cust: i.cust, cat: g('c'), amount: parseFloat(g('a')), status: 'open', assignee: S.role === 'owner' ? 'u1' : 'u2', due: '2026-11-27', expl: g('e'), created: TODAY }); audit('dispute.created', 'DSP-' + String(n).padStart(4, '0'), i.number); closeOv(); toast('Dispute opened — reminders for this invoice are paused'); go('#/disputes/' + id); };
ACT.newInvg = el => { const i = inv(el.dataset.id), ex = D.investigations.find(x => x.inv === i.id && !['resolved', 'dismissed'].includes(x.status)); if (ex) { toast('An investigation already exists'); return go('#/investigations/' + ex.id); } const n = D.investigations.length + 1, id = 'iv' + (++SEQ); D.investigations.push({ id, number: 'INVG-' + String(n).padStart(4, '0'), disc: null, title: `Manual investigation — ${i.number}`, cust: i.cust, inv: i.id, priority: 'medium', status: 'new', assignee: S.role === 'owner' ? 'u1' : 'u2', created: TODAY, version: 0, followUp: '', narrative: [], evidence: [], facts: [['Invoice ' + i.number + ' has a balance of ' + money(invBal(i), i.cur) + '.', []]], calcs: [{ label: 'Outstanding', expr: `${money(i.total, i.cur)} − ${money(invPaid(i) + invAdj(i), i.cur)} = ${money(invBal(i), i.cur)}` }], poss: [], unv: [], miss: [], recs: [], timeline: [[TODAY, 'Investigation opened manually', 'b']] }); audit('investigation.created', 'INVG-' + String(n).padStart(4, '0'), i.number); toast('Investigation opened'); go('#/investigations/' + id); };

/* ---------- import wizard & PDF review ---------- */
const IMP = {
  invoices: { file: 'invoices_oct_export.csv', size: '4.1 KB', headers: [['Invoice #', 'invoice_number'], ['Client', 'customer'], ['Date', 'issue_date'], ['Due', 'due_date'], ['Amount', 'total_amount'], ['Cur', 'currency'], ['PO', 'po_number']], total: 12, valid: 8, warn: 1, err: 1, dup: 2, rows: { valid: [['INV-1059', 'Lumen Education', '2026-11-13', '1,850.00'], ['INV-1060', 'Harbor & Finch LLP', '2026-11-13', '9,200.00'], ['INV-1061', 'Cobalt Energy Partners', '2026-11-13', '4,400.00']], warn: [['INV-1062', 'Quantum Freight', '03/04/2026', '3,100.00', 'Ambiguous date: 3 Apr or 4 Mar?']], err: [['INV-1063', 'Alder Health Systems', '2026-11-13', 'twelve hundred', 'Total is not a valid decimal amount']], dup: [['INV-1055', 'Harbor & Finch LLP', '2026-11-01', '15,600.00', 'Already exists — will be skipped, never overwritten'], ['INV-1056', 'Alder Health Systems', '2026-11-03', '9,300.00', 'Already exists — will be skipped, never overwritten']] } },
  payments: { file: 'bank_statement_nov.csv', size: '3.3 KB', headers: [['Posting date', 'date'], ['Amount', 'amount'], ['CCY', 'currency'], ['Description', 'reference'], ['Counterparty', 'payer_name']], total: 10, valid: 8, warn: 1, err: 0, dup: 1, rows: { valid: [['2026-11-13', 'ACME HOLDINGS', 'INV-1064', '2,300.00'], ['2026-11-13', 'NORTHWIND LABS', 'Nov services', '3,000.00']], warn: [['2026-11-13', 'UNKNOWN PAYER', 'wire', '640.00', 'No customer match — will import as unmatched']], err: [], dup: [['2026-11-12', 'ALDER HEALTH SYSTEMS', 'Nov payment', '17,800.00', 'Same fingerprint as PAY-0015 — skipped; confirm if genuinely a second payment']] } },
};
function importPage(kind) {
  const v = vs('imp', { kind, step: 1, tab: 'valid', pct: 0, headersSeen: false }); if (v.kind !== kind) { Object.assign(V.imp, { kind, step: 1, tab: 'valid', pct: 0 }); }
  const c = IMP[kind], steps = ['Upload', 'Map columns', 'Review', 'Import', 'Summary'];
  const st = `<div class="stepper">${steps.map((s, k) => `${k ? '<span class="sep"></span>' : ''}<span class="st ${v.step === k + 1 ? 'on' : v.step > k + 1 ? 'done' : ''}"><span class="n">${v.step > k + 1 ? '✓' : k + 1}</span>${s}</span>`).join('')}</div>`;
  let body = '';
  if (v.step === 1) body = `<div class="drop">${ic('up')}<p><b>Drag a CSV here</b>, or choose a file</p><p class="small muted">CSV up to 20 MB. Required columns: ${kind === 'invoices' ? 'invoice number, customer, issue date, due date, total, currency' : 'date, amount, currency'}.</p><div class="row mt16" style="justify-content:center"><button class="btn btn-primary" data-act="impNext">Use sample file: ${c.file}</button></div></div><div class="banner mt16">${ic('info')}<div>Prototype: no file is read. A sample is used. In the real product the file is hashed, and uploading the same file twice shows a warning.</div></div>`;
  if (v.step === 2) body = `<p class="mb16">We matched your columns. Your mapping is remembered for files with the same headers.</p>${table([{ h: 'Column in your file', f: h => `<b>${h[0]}</b>` }, { h: 'Maps to', f: h => `<select class="in"><option>${h[1]}</option><option>(ignore)</option></select>` }, { h: 'Sample', f: h => '<span class="muted">…</span>' }], c.headers)}${kind === 'payments' ? `<div class="field mt16"><label>Negative amounts in this file are…</label><select class="in"><option>Outgoing payments (imported, excluded from matching)</option><option>Reversals</option></select></div>` : `<div class="field mt16"><label>Date format</label><select class="in"><option>YYYY-MM-DD</option><option>DD/MM/YYYY</option><option>MM/DD/YYYY</option></select><div class="hint">Ambiguous dates must be confirmed.</div></div>`}`;
  if (v.step === 3) { const tabsL = [['valid', 'Valid', c.valid], ['warn', 'Warnings', c.warn], ['err', 'Errors', c.err], ['dup', 'Duplicates', c.dup]]; const rows = c.rows[v.tab]; body = `${tabs('imp.tab', tabsL, v.tab)}${rows.length ? table((kind === 'invoices' ? ['Number', 'Customer', 'Date', 'Total'] : ['Date', 'Payer', 'Reference', 'Amount']).map((h, k) => ({ h, cls: k === 3 ? 'num' : '', f: r => esc(r[k]) })).concat(v.tab === 'valid' ? [] : [{ h: 'Message', f: r => `<span class="badge b-${v.tab === 'err' ? 'red' : 'amber'} nodot">${esc(r[4])}</span>` }]), rows) : empty('No rows in this category.')}<div class="small muted mt8">${v.tab === 'valid' ? `Showing ${rows.length} of ${c.valid} valid rows.` : ''}</div>`; }
  if (v.step === 4) { body = `<p>Importing ${c.valid + c.warn} rows in the background…</p><div class="progress mt8"><i style="width:${v.pct}%"></i></div><div class="small muted mt8">${v.pct}% — a worker retry never creates duplicates (idempotent).</div>`; if (v.pct < 100) window.afterRender = () => setTimeout(() => { if (V.imp.step === 4) { V.imp.pct = Math.min(100, V.imp.pct + 25); if (V.imp.pct >= 100) { V.imp.step = 5; applyImport(kind); } render(); } }, 450); }
  if (v.step === 5) body = `<div class="banner ok">${ic('check')}<div><b>Import complete.</b> ${c.valid + c.warn} rows created, ${c.dup} skipped as duplicates, ${c.err} rejected.</div></div><div class="row wrap mt16"><button class="btn" data-act="toast" data-msg="Error rows downloaded (simulated)">${ic('dl')}Download error file</button><a class="btn btn-primary" href="${kind === 'invoices' ? '#/invoices' : '#/reconciliation'}">${kind === 'invoices' ? 'View invoices' : 'Go to reconciliation'}</a></div>`;
  const foot = v.step < 5 && v.step !== 4 ? `<div class="row mt24"><button class="btn" data-act="impBack" ${v.step === 1 ? 'disabled' : ''}>Back</button><span class="sp"></span><a class="btn btn-ghost" href="#/${kind}">Cancel</a>${v.step > 1 ? `<button class="btn btn-primary" data-act="impNext">${v.step === 3 ? `Import ${c.valid + c.warn} rows` : 'Continue'}</button>` : ''}</div>` : '';
  return `${pageH(kind === 'invoices' ? 'Import invoices' : 'Import payments', '', '', `<a href="#/${kind}">${kind === 'invoices' ? 'Invoices' : 'Payments'}</a> / Import`)}<div class="card"><div class="card-b">${st}${body}${foot}</div></div>`;
}
let impApplied = {};
function applyImport(kind) {
  if (impApplied[kind]) return; impApplied[kind] = true;
  if (kind === 'invoices') { D.invoices.push({ id: 'i59', number: 'INV-1059', cust: 'c7', issue: TODAY, due: '2026-12-13', total: 1850, cur: 'USD', life: 'issued', po: 'LE-322', desc: 'Imported' }, { id: 'i60', number: 'INV-1060', cust: 'c2', issue: TODAY, due: '2026-12-13', total: 9200, cur: 'USD', life: 'issued', po: '', desc: 'Imported' }); }
  audit('import.completed', 'Batch ' + Math.random().toString(16).slice(2, 6), kind + ': rows created, duplicates skipped');
}
ACT.impNext = () => { V.imp.step++; if (V.imp.step === 4) V.imp.pct = 0; render(); }; ACT.impBack = () => { V.imp.step--; render(); };
R(/^\/invoices\/import$/, () => importPage('invoices'), { name: 'imp' }); R(/^\/payments\/import$/, () => importPage('payments'), { name: 'imp' });
