/* ---------- payments ---------- */
R(/^\/payments$/, () => {
  const v = vs('payments', { q: '', f: 'all' });
  let rows = D.payments.filter(p => (p.number + p.payer + p.ref).toLowerCase().includes((v.q || '').toLowerCase()));
  const F = { unmatched: p => payAlloc(p) === 0, unallocated: p => payUnalloc(p) > 0, review: p => p.review, partial: p => payStatus(p) === 'partial' }; if (F[v.f]) rows = rows.filter(F[v.f]); rows = rows.sort((a, b) => b.date.localeCompare(a.date));
  return `${pageH('Payments', `${rows.length} of ${D.payments.length} shown`, `<a class="btn" href="#/payments/import">${ic('up')}Import CSV</a>${can('payments.manage') ? `<button class="btn btn-primary" data-act="recordPayment">${ic('plus')}Record payment</button>` : ''}`)}
  <div class="card"><div class="toolbar">${searchIn('payments.q', 'Search payer, reference, number')}${chipset('payments.f', [['all', 'All'], ['unallocated', 'Has unallocated'], ['unmatched', 'Unmatched'], ['review', 'Under review']], v.f)}</div>
  ${table([{ h: 'Payment', f: p => `<a href="#/payments/${p.id}"><b>${p.number}</b></a>` }, { h: 'Date', f: p => dt(p.date) }, { h: 'Payer (as received)', f: p => `${esc(p.payer)}<div class="small muted">${p.cust ? esc(cust(p.cust).name) : 'No customer match'}</div>` }, { h: 'Reference', f: p => `<span class="mono">${esc(p.ref)}</span>` }, { h: 'Amount', cls: 'num', f: p => money(p.amount, p.cur) }, { h: 'Allocated', cls: 'num', f: p => money(payAlloc(p), p.cur) }, { h: 'Unallocated', cls: 'num', f: p => `<b>${money(payUnalloc(p), p.cur)}</b>` }, { h: 'Status', f: p => badge(payStatus(p)) }, { h: 'Source', f: p => p.ver === 'source_verified' ? '<span class="badge b-teal nodot">Bank verified</span>' : '<span class="badge b-neutral nodot">Manual</span>' }], rows, { href: p => '#/payments/' + p.id })}</div>`;
}, { name: 'payments' });
R(/^\/payments\/(\w+)$/, m => {
  if (m[1] === 'import') return null; const p = pay(m[1]); if (!p) return null; const als = D.allocations.filter(a => a.pay === p.id), sug = D.matches.filter(x => x.pay === p.id && x.status === 'suggested'), dsc = D.discrepancies.filter(d => d.pay === p.id);
  return `${pageH(`${p.number} ${badge(payStatus(p))}`, `${esc(p.payer)} · ${dt(p.date)}`, `<button class="btn" data-act="addAlloc" data-id="${p.id}" ${payUnalloc(p) > 0 && can('reconciliation.allocate') ? '' : 'disabled'}>Allocate</button>${!p.reversed ? `<button class="btn" data-act="payReview" data-id="${p.id}">${p.review ? 'Clear review flag' : 'Mark under review'}</button><button class="btn btn-danger" data-act="payReverse" data-id="${p.id}">Mark reversed</button>` : ''}`, '<a href="#/payments">Payments</a> / ' + p.number)}
  ${dsc.map(d => `<div class="banner warn">${ic('info')}<div><b>${DTYPE[d.type]}</b> — ${d.number}. ${d.inv_id ? `<a href="#/investigations/${d.inv_id}">Open investigation</a>` : '<a href="#/reconciliation?tab=discrepancies">See discrepancy</a>'}</div></div>`).join('')}
  <div class="grid g-main"><div class="col">
  ${card('Amounts', `<div class="invbox" style="max-width:340px"><div><span>Payment amount</span><span>${money(p.amount, p.cur)}</span></div><div><span>Allocated</span><span>${money(payAlloc(p), p.cur)}</span></div><div class="t"><span>Unallocated</span><span>${money(payUnalloc(p), p.cur)}</span></div></div>`)}
  ${card('Allocations', als.length ? table([{ h: 'Invoice', f: a => `<a href="#/invoices/${a.inv}">${inv(a.inv).number}</a>` }, { h: 'Amount', cls: 'num', f: a => money(a.amount, p.cur) }, { h: 'Method', f: a => a.method.replace(/_/g, ' ') }, { h: 'State', f: a => a.voided ? badge('reversed') : badge('full') }, { h: '', f: a => !a.voided && can('reconciliation.allocate') ? `<button class="btn btn-sm" data-act="voidAlloc" data-id="${a.id}">Void</button>` : '' }], als) : empty('No allocations yet.'), '', true)}
  ${sug.length ? card('Suggested matches', sug.map(x => `<div class="ev"><div class="top"><b>Rule ${x.rule}</b>${badge(x.conf)}<span class="sp"></span><a class="btn btn-sm btn-primary" href="#/reconciliation">Review</a></div><div class="small mt8">${esc(x.why)}</div></div>`).join('')) : ''}
  </div><div class="col">
  ${card('Details', `<dl class="kv"><dt>Customer</dt><dd>${custLink(p.cust)}</dd><dt>Reference</dt><dd class="mono">${esc(p.ref)}</dd><dt>Method</dt><dd>${p.method}</dd><dt>Source</dt><dd>${esc(p.source)}</dd><dt>Verification</dt><dd>${p.ver === 'source_verified' ? '<span class="badge b-teal nodot">Bank verified</span>' : '<span class="badge b-neutral nodot">Manual — unverified</span>'}</dd></dl>`)}
  ${card('History', mini([`<li><span class="pt n"></span><div class="small">Imported from ${esc(p.source)}</div><div class="t">${dt(p.date)}</div></li>`, ...als.map(a => `<li><span class="pt n"></span><div class="small">Allocated ${money(a.amount, p.cur)} to ${inv(a.inv).number}${a.voided ? ' (voided)' : ''}</div><div class="t">${dt(a.at)}</div></li>`)]))}</div></div>`;
}, { name: 'paydetail' });
ACT.payReview = el => { const p = pay(el.dataset.id); p.review = !p.review; audit('payment.flag', p.number, p.review ? 'Marked under review' : 'Review cleared'); render(); };
ACT.payReverse = el => modal('Mark payment as reversed?', `<p>Reversing ${pay(el.dataset.id).number} voids all its allocations and reopens the affected invoice balances in one transaction. This is audit-logged.</p>`, `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-danger" data-act="doReverse" data-id="${el.dataset.id}">Reverse payment</button>`);
ACT.doReverse = el => { const p = pay(el.dataset.id); D.allocations.filter(a => a.pay === p.id).forEach(a => a.voided = true); p.reversed = true; audit('payment.reversed', p.number, 'Allocations voided'); closeOv(); toast('Payment reversed; invoice balances restored'); render(); };
ACT.voidAlloc = el => modal('Void allocation', form('fv', fld('Reason', '<input class="in" data-req name="r">')) + '<p class="small muted">The allocation stays in the history as voided. Older allocations may require approval in the real product.</p>', `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="doVoid" data-id="${el.dataset.id}">Void allocation</button>`);
ACT.doVoid = el => { if (!validate($('#fv'))) return; const a = byId(D.allocations, el.dataset.id); a.voided = true; audit('allocation.voided', `${pay(a.pay).number} → ${inv(a.inv).number}`, money(a.amount)); closeOv(); toast('Allocation voided'); render(); };
ACT.addAlloc = el => { const p = pay(el.dataset.id); modal('Allocate payment', `<p class="small muted mb16">Unallocated: <b>${money(payUnalloc(p), p.cur)}</b>. Allocation is all-or-nothing and limited by the invoice balance.</p><div id="alerr"></div>` + form('fl', fld('Invoice', `<select class="in" data-req name="i"><option value="">Select…</option>${openInvoices().filter(i => i.cur === p.cur && (!p.cust || i.cust === p.cust)).map(i => `<option value="${i.id}">${i.number} — ${esc(cust(i.cust).name)} — ${money(invBal(i), i.cur)} due</option>`).join('')}</select>`) + fld('Amount', `<input class="in num" data-money name="a" inputmode="decimal" value="${payUnalloc(p)}">`, '', 'Enter an amount greater than 0')), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="doAlloc" data-id="${p.id}">Allocate</button>`); };
ACT.doAlloc = el => { const f = $('#fl'); if (!validate(f)) return; const e = allocate(el.dataset.id, $('[name=i]', f).value, parseFloat($('[name=a]', f).value), 'manual'); if (e) { $('#alerr').innerHTML = `<div class="banner danger">${ic('info')}<div>${e} (422 business_rule_violation)</div></div>`; return; } closeOv(); toast('Allocation created'); render(); };
